      if (alt === undefined) {
        (SCHWER.has(v.impact) ? fehler : warnungen).push(`${schluessel}: neue Regel ${v.id} (${v.impact}, ${v.knoten}×) – ${v.hilfe} → ${v.ziele.join(" | ")}`);
      } else if (v.knoten > alt) {
        warnungen.push(`${schluessel}: ${v.id} (${v.impact}) ${alt} → ${v.knoten} Elemente`);
