            const s = r.verstoesse ? r.verstoesse.filter((v) => SCHWER.has(v.impact)).length : "?";
            console.log(`  ${schluessel.padEnd(44)} ${r.fehler ? "FEHLER " + r.fehler : `${r.verstoesse.length} Regeln verletzt (${s} serious/critical)`}  ${zeit(t)}`);
